#include "PluginEditor.h"
#include "BinaryData.h"
DrumAliveAudioProcessorEditor::DrumAliveAudioProcessorEditor(DrumAliveAudioProcessor& proc):AudioProcessorEditor(&proc),p(proc){setSize(760,440);bg=juce::ImageCache::getFromMemory(BinaryData::snare_jpg,BinaryData::snare_jpgSize);title.setText("DRUMALIVE   /   SAMPLE RESYNTHESIS",juce::dontSendNotification);title.setColour(juce::Label::textColourId,juce::Colours::white);title.setFont(juce::Font(18,juce::Font::bold));addAndMakeVisible(title);addAndMakeVisible(load);load.onClick=[this]{juce::FileChooser fc("Load one-shot");if(fc.browseForFileToOpen())p.loadSample(fc.getResult());};const char* ids[]={"variation","humanize","tone","decay","output"};for(int i=0;i<5;++i){knobs[i]=std::make_unique<juce::Slider>();knobs[i]->setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);knobs[i]->setTextBoxStyle(juce::Slider::TextBoxBelow,false,70,20);knobs[i]->setColour(juce::Slider::rotarySliderFillColourId,juce::Colour(0xff69d4d0));addAndMakeVisible(*knobs[i]);attaches[i]=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.state,ids[i],*knobs[i]);}}
void DrumAliveAudioProcessorEditor::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xe8122027));if(!bg.isNull()){g.setOpacity(.20f);g.drawImageWithin(bg,0,0,getWidth(),getHeight(),juce::RectanglePlacement::centred);g.setOpacity(1);}g.setColour(juce::Colours::white.withAlpha(.8f));const char* names[]={"VARIATION","HUMANIZE","TONE","DECAY","OUTPUT"};for(int i=0;i<5;++i)g.drawText(names[i],30+i*145,155,120,20,juce::Justification::centred);g.setColour(juce::Colour(0xff69d4d0));g.drawText(p.sampleName,30,105,500,24,juce::Justification::left);}
void DrumAliveAudioProcessorEditor::resized(){title.setBounds(28,24,600,35);load.setBounds(28,65,150,30);for(int i=0;i<5;++i)knobs[i]->setBounds(30+i*145,180,120,150);}
